<html lang="zh-CN">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>剧情选项</title>
    <style>
      .choice-box {
        background: #2a2826;
        border: 1px solid #4a443e;
        border-radius: 6px;
        padding: 10px;
        font-size: 0.9em;
        box-shadow: 0 1px 3px rgba(80, 60, 40, 0.06);
      }

      .choice-title {
        color: #b0a89c;
        font-size: 0.85em;
        margin-bottom: 8px;
        padding-left: 2px;
        letter-spacing: 0.5px;
      }

      .choice-item {
        background: #353230;
        border: 1px solid #4a443e;
        border-left: 3px solid #a8b8c4;
        border-radius: 4px;
        padding: 7px 10px;
        color: #c8d2dc;
        cursor: pointer;
        transition: all 0.2s;
      }

      .choice-item:hover {
        background: #3a3631;
        border-left-color: #8d9eaa;
        color: #d8e0e8;
      }

      .choice-item:active {
        transform: scale(0.98);
      }
    </style>
  </head>
  <body>
    <div style="margin: 8px 0">
      <div class="choice-box">
        <div class="choice-title">▸ 剧情选项</div>
        <div id="choice-list" style="display: flex; flex-direction: column; gap: 6px;"></div>
      </div>
    </div>

    <script>
      (function () {
        // 1. 获取当前消息内容（兼容 iframe）
        function getCurrentMessageContent() {
          const _getChatMessages = window.getChatMessages || (window.parent && window.parent.getChatMessages);
          const _getCurrentMessageId = window.getCurrentMessageId || (window.parent && window.parent.getCurrentMessageId);
          if (typeof _getChatMessages === 'function' && typeof _getCurrentMessageId === 'function') {
            try {
              const msgId = _getCurrentMessageId();
              const msgs = _getChatMessages(msgId);
              if (msgs && msgs.length > 0) return msgs[0].message;
            } catch (e) { console.error(e); }
          }
          return null;
        }

        // 2. 解析 <Choice>...</Choice> 内每一行作为一个选项
        //    抓取时把英文直引号 " 换成弯引号 “”：成对 "…"→“…”、落单 "→”。
        //    必须用函数替换，不能用美元数字捕获引用——酒馆正则的 replace 会把它当外层捕获组吃掉（会变乱码数字）。
        //    填入走 /setinput 时，STScript 把直引号当参数分隔符会截断，弯引号则按字面填入。
        function normQuotes(s) {
          return s.replace(/"([^"]*)"/g, function (m, inner) { return '“' + inner + '”'; }).replace(/"/g, '”');
        }
        function parseChoices(content) {
          if (!content) return [];
          const match = content.match(/<Choice>([\s\S]*?)<\/Choice>/i);
          if (!match) return [];
          return match[1].split('\n').map(l => normQuotes(l.trim())).filter(l => l.length > 0);
        }

        // 3. 渲染选项列表
        function render() {
          const container = document.getElementById('choice-list');
          if (!container) return;

          const content = getCurrentMessageContent();
          if (!content) {
            container.innerHTML = '<div style="color:#aaa;text-align:center;">无法获取消息内容</div>';
            return;
          }

          const choices = parseChoices(content);
          if (choices.length === 0) {
            container.innerHTML = '<div style="color:#aaa;text-align:center;">无选项</div>';
            return;
          }

          let html = '';
          choices.forEach(function (text) {
            const safe = text.replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
            html += '<div class="choice-item" onclick="selectChoice(this)" data-send-text="' + safe + '">' + safe + '</div>';
          });
          container.innerHTML = html;
        }

        // 4. 点击 → 填入输入框
        window.selectChoice = function (el) {
          var text = el.getAttribute('data-send-text');
          if (!text) return;
          var _triggerSlash = window.triggerSlash || (window.parent && window.parent.triggerSlash);
          if (typeof _triggerSlash === 'function') {
            _triggerSlash('/setinput ' + text);
          }
        };

        // 5. 延迟执行渲染
        setTimeout(render, 100);
      })();
    </script>
  </body>
</html> 
