<div id="hb-forum-root"></div>
<script>
  (function () {
    // 1. 取当前楼层原文（iframe 安全，沿用剧情选项的方式）
    function getMsg() {
      var _get = window.getChatMessages || (window.parent && window.parent.getChatMessages);
      var _id = window.getCurrentMessageId || (window.parent && window.parent.getCurrentMessageId);
      if (typeof _get === 'function' && typeof _id === 'function') {
        try { var ms = _get(_id()); if (ms && ms.length > 0) return ms[0].message; }
        catch (e) { console.error(e); }
      }
      return null;
    }
    // 2. 日夜：读控制面板存的主题（同源 localStorage 可读），读不到则浅色
    function getTheme() {
      try { var t = JSON.parse(localStorage.getItem('hb-panel-theme')); if (t === 'dark' || t === 'light') return t; } catch (e) {}
      try { var t2 = JSON.parse(window.parent.localStorage.getItem('hb-panel-theme')); if (t2 === 'dark' || t2 === 'light') return t2; } catch (e) {}
      return 'light';
    }
    function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
    // 名字里含「回复」就切成 楼主/被回复者
    function splitName(n) {
      var i = n.indexOf('回复');
      if (i >= 0) return { poster: n.slice(0, i).trim(), target: n.slice(i + 2).trim() };
      return { poster: n.trim(), target: null };
    }
    function parseForum(content) {
      if (!content) return null;
      var m = content.match(/<Forum>([\s\S]*?)<\/Forum>/i);
      if (!m) return null;
      var lines = m[1].split('\n').map(function (s) { return s.trim(); }).filter(function (s) { return s.length > 0; });
      if (lines.length === 0) return null;
      var title = lines[0].replace(/[{}]/g, '').trim();
      var floors = lines.slice(1).map(function (line, i) {
        var ci = line.search(/[：:]/);                 // 首个冒号为界（不用正则尾锚，避免被酒馆正则吃掉美元符）
        var namePart, contentPart;
        if (ci >= 0) { namePart = line.slice(0, ci); contentPart = line.slice(ci + 1); }
        else { namePart = ''; contentPart = line; }
        namePart = namePart.replace(/[{}]/g, '').trim();
        contentPart = contentPart.replace(/[{}]/g, '').trim();
        var sn = splitName(namePart);
        return { poster: sn.poster, target: sn.target, content: contentPart, label: (i === 0 ? '楼主' : i + 'L'), isOP: i === 0 };
      });
      return { title: title, floors: floors };
    }
    // 按网名锁色：首次出现取下一个色，之后（含被回复）复用同色
    function makeColorOf(floors, pal) {
      var map = {}, n = 0;
      function get(name) {
        if (!name) return pal[0];
        if (!(name in map)) { map[name] = pal[n % pal.length]; n++; }
        return map[name];
      }
      floors.forEach(function (f) { get(f.poster); if (f.target) get(f.target); });
      return get;
    }
    var PAL = {
      light: ['#e0848f', '#5fa9a0', '#d39a52', '#8a86c9', '#d77f6a', '#6f9bcf', '#cf7fa6'],
      dark:  ['#f0939f', '#79c4ba', '#e8b06a', '#a6a2e0', '#ef9c86', '#8fb4e0', '#e295bd']
    };
    function render() {
      var root = document.getElementById('hb-forum-root');
      if (!root) return;
      var data = parseForum(getMsg());
      if (!data) { root.innerHTML = ''; return; }
      var theme = getTheme();
      var colorOf = makeColorOf(data.floors, PAL[theme]);
      var posts = '';
      data.floors.forEach(function (f) {
        var x = colorOf(f.poster);
        var meta = '<span class="hbf-uname" style="color:' + x + '">' + esc(f.poster || '匿名') + '</span>';
        if (f.target) {
          var y = colorOf(f.target);
          meta += '<span class="hbf-reply">回复</span><span class="hbf-uname" style="color:' + y + '">' + esc(f.target) + '</span>';
        }
        posts += '<div class="hbf-post' + (f.isOP ? ' op' : '') + '" style="border-left-color:' + x + '">'
          + '<div class="hbf-chip" style="background:' + x + '22;color:' + x + '">' + esc(f.label) + '</div>'
          + '<div class="hbf-main"><div class="hbf-meta">' + meta + '</div>'
          + '<div class="hbf-content">' + esc(f.content) + '</div></div></div>';
      });
      root.innerHTML = '<div class="hbf-forum ' + theme + '"><div class="hbf-head"><span class="hbf-dot">💬</span>'
        + '<span class="hbf-title">' + esc(data.title) + '</span></div>'
        + '<div class="hbf-body">' + posts + '</div></div>';
    }
    setTimeout(render, 100);
  })();
</script>
</body>
</html>
