  // ============== localStorage 工具 ==============
  function lsRead(key, fallback) {
    try {
      const v = localStorage.getItem(key);
      return v ? JSON.parse(v) : fallback;
    } catch (e) { return fallback; }
  }
  function lsWrite(key, value) {
    try { localStorage.setItem(key, JSON.stringify(value)); } catch (e) {}
  }

  function capitalize(s) { return s ? s.charAt(0).toUpperCase() + s.slice(1) : s; }
  function escHtml(s) {
    return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }
  function bracketOf(name) { const m = name && name.match(/\[(.+?)\]/); return m ? m[1] : null; }
  function styleLabel(preset, s) {
    try { const e = preset && preset.prompts.find(x => x.id === s.id); if (!e) return s.key; return bracketOf(e.name) || e.name; }
    catch (err) { return s.key; }
  }
  function styleFullName(preset, s) {
    try { const e = preset && preset.prompts.find(x => x.id === s.id); return e ? e.name : s.key; }
    catch (err) { return s.key; }
  }
  function detectVar(preset, entryId, varName) {
    const e = preset.prompts.find(x => x.id === entryId);
    if (!e || !e.content) return '';
    const m = e.content.match(new RegExp('setvar::' + varName + '::\\s*([^}]*)'));
    return (m && m[1]) ? m[1].trim() : '';
  }
  function getVarSafe(entryId, varName) {
    try { return detectVar(getPreset('in_use'), entryId, varName); } catch (e) { return ''; }
  }

  // 自动检测当前的正文标签词：从🗺️正文 prompt 的 <xxx> 标签拿
  function detectCurrentTag(preset) {
    const p = preset.prompts.find(x => x.id === TEXT_PROMPT_ID);
    if (!p || !p.content) return 'scene';
    const m = p.content.match(/<([A-Za-z][A-Za-z0-9_]*)>/);
    if (m && m[1]) return m[1].toLowerCase();
    return 'scene';
  }
  function getCurrentTagSafe() {
