  // ============== 业务：检测当前状态 ==============
  function detectModel(preset) {
    const enabled = new Set(preset.prompts.filter(p => p.enabled).map(p => p.id));
    if (enabled.has(E.Claude_Special)) return 'claude';
    if (enabled.has(E.DS_Special))     return 'deepseek';
    if (enabled.has(E.Gemini_Special)) return 'gemini';
    return null;
  }

  function detectPOV(preset) {
    const entry = preset.prompts.find(p => p.id === POV_ENTRY_ID);
    if (!entry || !entry.content) return null;
    const m = entry.content.match(/setvar::POV::\s*([^\s}]+)/);
    return (m && m[1]) ? m[1].trim() : null;
  }

  function detectFromGroup(preset, options) {
    const enabled = new Set(preset.prompts.filter(p => p.enabled).map(p => p.id));
    for (const opt of options) {
      if (opt.id && enabled.has(opt.id)) return opt.key;
    }
    const nullOpt = options.find(o => o.id === null);
    return nullOpt ? nullOpt.key : null;
  }

  function detectMode(preset) {
    const enabled = new Set(preset.prompts.filter(p => p.enabled).map(p => p.id));
    for (const m of MODES) {
