  function detectEnhance(preset) {
    const enabled = new Set(preset.prompts.filter(p => p.enabled).map(p => p.id));
    const out = {};
    ENHANCE_ITEMS.forEach(it => { out[it.key] = enabled.has(it.id); });
    return out;
