  // >>> 1.6-b MEMORY REGEX FALLBACK GUARD >>>
  // 记忆脚本能运行时由它自己维护动态深度；它缺失/被禁用时，只有外层控制面板
  // 仍有机会把两条固定正则恢复到安全默认值。这里只改深度，不碰 enabled。
  const MEMORY_ARCHIVER_SCRIPT_ID = '574b118e-eab9-4d97-995b-399fedaf1dc9';
  const MEMORY_FLUX_REGEX_ID = '1a7548c3-d1c5-4fc2-8955-1933510e164c';
  const MEMORY_ARCHIVE_REGEX_ID = 'dd0c4c41-36dd-4c99-87bc-6e77eec4252e';
  const MEMORY_REGEX_TARGET = { type: 'preset', name: 'in_use' };
  const MEMORY_REGEX_GUARD_INTERVAL_MS = 60 * 1000;

  let memoryRegexGuardTimer = null;
  let memoryRegexGuardInterval = null;
  let memoryRegexGuardRunning = false;
  let memoryRegexGuardQueued = false;
  let memoryRegexGuardDestroyed = false;
  const memoryRegexGuardWarnings = new Set();

  function warnMemoryRegexGuardOnce(key, message, error) {
    if (memoryRegexGuardWarnings.has(key)) return;
    memoryRegexGuardWarnings.add(key);
    if (error === undefined) console.warn(`[此间小镇] ${message}`);
    else console.warn(`[此间小镇] ${message}`, error);
  }

  // true=找到且整条父链都启用；false=缺失/禁用；null=运行时无法判断（fail-open）。
  function isMemoryArchiverEffectivelyEnabled() {
    if (typeof getScriptTrees !== 'function') {
      warnMemoryRegexGuardOnce(
        'missing-getScriptTrees',
        '缺少 getScriptTrees，记忆正则外部保险已跳过（不会覆盖动态深度）'
      );
      return null;
    }

    let trees;
    try {
      trees = getScriptTrees({ type: 'preset' });
    } catch (error) {
      warnMemoryRegexGuardOnce('getScriptTrees-failed', '读取预设脚本树失败，已跳过外部保险', error);
      return null;
    }

    let found = false;
    let enabled = false;
    const walk = (nodes, parentEnabled) => {
      for (const node of Array.isArray(nodes) ? nodes : []) {
        const effective = parentEnabled && node && node.enabled !== false;
        if (node && node.type === 'script') {
          if (node.id === MEMORY_ARCHIVER_SCRIPT_ID) {
            found = true;
            enabled = enabled || effective;
          }
          continue;
        }
        if (node && node.type === 'folder') walk(node.scripts, effective);
      }
    };
    walk(trees, true);
    return found && enabled;
  }

  // true=两条正则存在且深度偏离；false=已经正确；null=无法安全判断。
  function memoryRegexDefaultsNeedRestore() {
    if (typeof getTavernRegexes !== 'function') {
      warnMemoryRegexGuardOnce(
        'missing-getTavernRegexes',
        '缺少 getTavernRegexes，记忆正则外部保险已跳过'
      );
      return null;
    }

    let regexes;
    try {
      regexes = getTavernRegexes(MEMORY_REGEX_TARGET);
    } catch (error) {
      warnMemoryRegexGuardOnce('getTavernRegexes-failed', '读取预设正则失败，已跳过外部保险', error);
      return null;
    }

    const flux = regexes.find(regex => regex.id === MEMORY_FLUX_REGEX_ID);
    const archive = regexes.find(regex => regex.id === MEMORY_ARCHIVE_REGEX_ID);
    if (!flux || !archive) {
      const missing = [
        ...(!flux ? [MEMORY_FLUX_REGEX_ID] : []),
        ...(!archive ? [MEMORY_ARCHIVE_REGEX_ID] : []),
      ];
      warnMemoryRegexGuardOnce(
        `missing-regex:${missing.join(',')}`,
        `预设缺少记忆正则 ${missing.join('、')}，外部保险不会尝试创建条目`
      );
      return null;
    }

    return flux.min_depth !== 11 || flux.max_depth !== 50 ||
      archive.min_depth !== 51 || archive.max_depth !== null;
  }

  async function reconcileMemoryRegexDefaults() {
    if (memoryRegexGuardDestroyed) return;
    if (memoryRegexGuardRunning) {
      memoryRegexGuardQueued = true;
      return;
    }

    memoryRegexGuardRunning = true;
    try {
      do {
        memoryRegexGuardQueued = false;

        // 记忆脚本启用时，无论内部两个功能开关如何，都由记忆脚本自己负责。
        const memoryEnabled = isMemoryArchiverEffectivelyEnabled();
        if (memoryEnabled !== false) continue;
        if (memoryRegexDefaultsNeedRestore() !== true) continue;

        // 只读预检和慢写之间再次确认，避免用户恰在此刻重新启用脚本。
        if (isMemoryArchiverEffectivelyEnabled() !== false) continue;
        if (typeof updateTavernRegexesWith !== 'function') {
          warnMemoryRegexGuardOnce(
            'missing-updateTavernRegexesWith',
            '缺少 updateTavernRegexesWith，无法恢复记忆正则默认深度'
          );
          continue;
        }

        await updateTavernRegexesWith(
          regexes => {
            for (const regex of regexes) {
              if (regex.id === MEMORY_FLUX_REGEX_ID) {
                regex.min_depth = 11;
                regex.max_depth = 50;
              } else if (regex.id === MEMORY_ARCHIVE_REGEX_ID) {
                regex.min_depth = 51;
                regex.max_depth = null;
              }
            }
            return regexes;
          },
          MEMORY_REGEX_TARGET
        );
        console.info('[此间小镇] 记忆脚本未运行，已恢复正则默认深度 11–50 / 51–∞');
      } while (memoryRegexGuardQueued && !memoryRegexGuardDestroyed);
    } catch (error) {
      warnMemoryRegexGuardOnce('restore-failed', '恢复记忆正则默认深度失败', error);
    } finally {
      memoryRegexGuardRunning = false;
      if (memoryRegexGuardQueued && !memoryRegexGuardDestroyed) scheduleMemoryRegexGuard(0);
    }
  }

  function scheduleMemoryRegexGuard(delay = 0) {
    if (memoryRegexGuardDestroyed) return;
    if (memoryRegexGuardTimer !== null) clearTimeout(memoryRegexGuardTimer);
    memoryRegexGuardTimer = setTimeout(() => {
      memoryRegexGuardTimer = null;
      void reconcileMemoryRegexDefaults();
    }, Math.max(0, delay));
  }

  function startMemoryRegexGuard() {
    if (memoryRegexGuardDestroyed || memoryRegexGuardInterval !== null) return;
    scheduleMemoryRegexGuard(1000);
    memoryRegexGuardInterval = setInterval(
      () => scheduleMemoryRegexGuard(0),
      MEMORY_REGEX_GUARD_INTERVAL_MS
    );
  }

  function destroyMemoryRegexGuard() {
    memoryRegexGuardDestroyed = true;
    memoryRegexGuardQueued = false;
    if (memoryRegexGuardTimer !== null) clearTimeout(memoryRegexGuardTimer);
    if (memoryRegexGuardInterval !== null) clearInterval(memoryRegexGuardInterval);
    memoryRegexGuardTimer = null;
    memoryRegexGuardInterval = null;
  }
  // <<< 1.6-b MEMORY REGEX FALLBACK GUARD <<<

  // ============== 日夜配色：按钮直接改写正则 content 里的颜色 ==============
  // 单条正则，content 默认浅色；按位置把每条正则的颜色换成目标主题那一套。
  // 位置改写与当前内容无关，幂等，不存在反向歧义。
  async function applyBeautyTheme(theme) {
    const idx = (theme === 'dark') ? 1 : 0;
    try {
      await updateTavernRegexesWith(
        regexes => {
          regexes.forEach(r => {
            const map = BEAUTY_COLORS[r.id];
            if (!map) return;
            let i = 0;
            r.replace_string = r.replace_string.replace(BEAUTY_HEX, m => {
              const pair = map[i++];
              return pair ? pair[idx] : m;
            });
          });
          return regexes;
        },
        { type: 'preset', name: 'in_use' }
