  async function switchModel(model) {
    try {
      const onSet  = new Set(model.on);
      const offSet = new Set(model.off);
      let didDefaultNarrative = false;

      await updatePresetWith('in_use', preset => {
        preset.prompts.forEach(p => {
          if (onSet.has(p.id))  p.enabled = true;
          if (offSet.has(p.id)) p.enabled = false;
        });
        if (model.key === 'claude' || model.key === 'gemini') {
          const anyModeOn = preset.prompts.some(p =>
            MODE_IDS.includes(p.id) && p.enabled);
          if (!anyModeOn) {
            const narrative = preset.prompts.find(p => p.id === E.Mode_Narrative);
            if (narrative) {
              narrative.enabled = true;
              didDefaultNarrative = true;
            }
          }
        }
        return preset;
      }, { render: 'immediate' });

      const regexShouldEnable = (model.key !== 'deepseek');
      await setRegexEnabled(REGEX_DS_OFF, regexShouldEnable);

      const extras = [];
      if (didDefaultNarrative) extras.push('已自动启用叙事模式');
      extras.push(regexShouldEnable ? '总结类正则已开启' : '总结类正则已关闭');
      const extra = extras.length ? `（${extras.join('；')}）` : '';
      toastr.success(`已切换为 ${model.label}${extra}`);
