      const preset = getPreset('in_use');
      // ST 把 prompt_order 里有的归到 prompts；没在 order 里的归到 prompts_unused
      // 都查一遍，无论用户在 ST 里怎么动开发手册都能读到
      const inList   = (preset.prompts || []).find(x => x.id === MANUAL_PROMPT_ID);
      const inUnused = (preset.prompts_unused || []).find(x => x.id === MANUAL_PROMPT_ID);
