  // 解析 markdown 缩进列表为树（每节点 = { text, children: [...] }）
  function parseManual(md) {
    if (!md) return [];
    const lines = md.split('\n').filter(l => l.trim());
    const root = { text: 'root', children: [], level: -1 };
    const stack = [root];
    for (const line of lines) {
      const m = line.match(/^(\s*)-\s+(.*)$/);
      if (!m) continue;
      const indent = m[1].length;
      const level = Math.floor(indent / 2);
      const node = { text: m[2].trim(), children: [], level };
      while (stack.length > 1 && stack[stack.length - 1].level >= level) {
        stack.pop();
      }
      stack[stack.length - 1].children.push(node);
      stack.push(node);
    }
    return root.children;
  }

  function renderManualInline(text) {
    return String(text)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/`([^`]+)`/g, '<code>$1</code>')
      .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  }

  function escapeManualAttr(s) {
    return String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;');
  }

  function ensureManualLoaded() {
    if (manualState.tree === null) {
      manualState.tree = parseManual(getManualContent());
      // 默认展开所有顶层 + 选中第一个有详情的节点
      manualState.tree.forEach(n => manualState.openNodes.add(n.text));
      if (!manualState.selectedPath) {
        outer: for (const top of manualState.tree) {
          for (const child of top.children) {
            if (child.children.length > 0) {
              manualState.selectedPath = [top.text, child.text];
              break outer;
            }
          }
        }
        if (!manualState.selectedPath && manualState.tree[0]) {
          const t = manualState.tree[0];
          if (t.children[0]) manualState.selectedPath = [t.text, t.children[0].text];
          else manualState.selectedPath = [t.text];
        }
      }
    }
  }

  function buildManualHTML() {
    ensureManualLoaded();
    if (!manualState.tree.length) {
      return '<div class="hb-manual"><div class="hb-manual-tree"></div><div class="hb-manual-divider"></div><div class="hb-manual-detail"><div class="hb-manual-empty">开发手册尚未编写。<br>请编辑 prompt「开发手册」的 content，按 markdown 缩进列表书写。</div></div></div>';
    }
    let html = '<div class="hb-manual">';
    html += '<div class="hb-manual-tree">';
    manualState.tree.forEach(top => {
      const isOpen = manualState.openNodes.has(top.text);
      const hasChildren = top.children.length > 0;
      const isSelected = !hasChildren && manualState.selectedPath && manualState.selectedPath.length === 1 && manualState.selectedPath[0] === top.text;
      html += `<div class="hb-manual-node ${hasChildren ? '' : 'leaf'} ${isOpen ? 'open' : ''} ${isSelected ? 'selected' : ''}" data-level="1" data-path="${escapeManualAttr(top.text)}">`;
      html += `<span class="arrow">▸</span><span class="hb-manual-node-text">${renderManualInline(top.text)}</span>`;
      html += '</div>';
      html += `<div class="hb-manual-children ${isOpen ? 'open' : ''}">`;
      top.children.forEach(child => {
        const childSelected = manualState.selectedPath && manualState.selectedPath.length === 2 &&
                              manualState.selectedPath[0] === top.text &&
                              manualState.selectedPath[1] === child.text;
        html += `<div class="hb-manual-node leaf ${childSelected ? 'selected' : ''}" data-level="2" data-top="${escapeManualAttr(top.text)}" data-child="${escapeManualAttr(child.text)}">`;
        html += `<span class="arrow">▸</span><span class="hb-manual-node-text">${renderManualInline(child.text)}</span>`;
        html += '</div>';
      });
      html += '</div>';
    });
    html += '</div>';
    html += '<div class="hb-manual-divider"></div>';
    html += '<div class="hb-manual-detail">';
    html += renderManualDetail();
    html += '</div>';
    html += '</div>';
    return html;
  }

  function renderManualDetail() {
    const path = manualState.selectedPath;
    if (!path) return '<div class="hb-manual-empty">请从左侧选择条目</div>';
    let node = { children: manualState.tree };
    for (const seg of path) {
      const next = node.children.find(c => c.text === seg);
      if (!next) return '<div class="hb-manual-empty">条目未找到</div>';
      node = next;
    }
    if (!node.children || node.children.length === 0) {
      return `<h4>${renderManualInline(node.text)}</h4><div class="hb-manual-empty">（此条目暂无详细说明）</div>`;
    }
    let html = `<h4>${renderManualInline(node.text)}</h4>`;
    html += renderManualTreeAsUl(node.children);
    return html;
  }

  function renderManualTreeAsUl(nodes) {
    let html = '<ul>';
    nodes.forEach(n => {
      html += `<li>${renderManualInline(n.text)}`;
      if (n.children && n.children.length > 0) {
        html += renderManualTreeAsUl(n.children);
      }
      html += '</li>';
    });
    html += '</ul>';
    return html;
  }

  // ============== 业务：思考增强 ==============
  async function toggleEnhanceItem(key) {
    const item = ENHANCE_ITEMS.find(i => i.key === key);
    if (!item) return;
    let newState = null;
    try {
      await updatePresetWith('in_use', preset => {
        const p = preset.prompts.find(x => x.id === item.id);
        if (!p) return preset;
        p.enabled = !p.enabled;
        newState = p.enabled;
        return preset;
      }, { render: 'immediate' });
      if (newState !== null) {
        toastr.success(`${item.key} ${newState ? '已开启' : '已关闭'}`);
      }
      syncPanelState();
    } catch (e) {
      console.error('[此间小镇] 切换思考增强子项失败:', e);
      toastr.error('操作失败，详见控制台');
    }
  }

  async function toggleWidgetItem(key) {
    const item = WIDGETS.find(i => i.key === key);
    if (!item) return;
    let newState = null;
    try {
      await updatePresetWith('in_use', preset => {
        const p = preset.prompts.find(x => x.id === item.id);
        if (!p) return preset;
        p.enabled = !p.enabled;
        newState = p.enabled;
        return preset;
      }, { render: 'immediate' });
      if (newState !== null) toastr.success(item.key + ' ' + (newState ? '已开启' : '已关闭'));
      syncPanelState();
    } catch (e) {
      console.error('[此间小镇] 切换小组件失败:', e);
      toastr.error('操作失败，详见控制台');
    }
  }

  async function applyEnhanceAction(action) {
    if (action.kind === 'placeholder') {
      toastr.info('待配置位置（占位）');
      return;
    }
    if (action.kind === 'clear') {
      const ids = new Set(ENHANCE_ITEMS.map(i => i.id));
      try {
        await updatePresetWith('in_use', preset => {
          preset.prompts.forEach(p => { if (ids.has(p.id)) p.enabled = false; });
          return preset;
        }, { render: 'immediate' });
        toastr.success(`已清空全部 ${ENHANCE_ITEMS.length} 项思考增强`);
        syncPanelState();
      } catch (e) {
        console.error('[此间小镇] 清空思考增强失败:', e);
        toastr.error('清空失败，详见控制台');
      }
      return;
    }
    if (action.kind === 'preset') {
      const targetIds = new Set(
        action.enables
          .map(k => ENHANCE_ITEMS.find(i => i.key === k))
          .filter(Boolean)
          .map(i => i.id)
      );
      try {
        await updatePresetWith('in_use', preset => {
          preset.prompts.forEach(p => { if (targetIds.has(p.id)) p.enabled = true; });
          return preset;
        }, { render: 'immediate' });
        toastr.success(`已应用「${action.label}」：${action.enables.join(' + ')}`);
        syncPanelState();
      } catch (e) {
        console.error('[此间小镇] 应用思考增强组合失败:', e);
        toastr.error('应用失败，详见控制台');
      }
      return;
    }
  }

  // ============== 业务：正文标签替换（phrase 定位法）==============
  // 策略：
  //   1. 自动从🗺️正文 prompt 检测当前 tag
  //   2. 在所有 baseline prompts 里 case-insensitive 全替换为新 tag 的小写形式
  //   3. 用 UPPER_PHRASE_PATTERNS 把"必须大写位"的特定上下文 phrase 回正为首字母大写

  function scanTagFootprint(preset, currentTag) {
    // 扫描每个 baseline prompt 里 case-insensitive 匹配的总数
    const escaped = currentTag.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const re = new RegExp(`(?<![A-Za-z0-9_])${escaped}(?![A-Za-z0-9_])`, 'gi');
    return TAG_BASELINE.map(b => {
      const p = preset.prompts.find(x => x.id === b.id);
      if (!p || !p.content) return { ...b, found: 0, missing: true, expect: b.lower + b.upper };
      const count = (p.content.match(re) || []).length;
      return { ...b, found: count, missing: false, expect: b.lower + b.upper };
    });
  }

  function scanPhraseFootprint(preset, currentTag) {
    const tagLower = currentTag.toLowerCase();
    return UPPER_PHRASE_PATTERNS.map(up => {
      const p = preset.prompts.find(x => x.id === up.promptId);
      if (!p || !p.content) return { ...up, count: 0, missing: true };
      const built = up.build(tagLower);
      return { ...up, count: (p.content.match(built.find) || []).length, missing: false };
    });
  }

  function showTagConfirm({fromTag, toLower, toUpper, scan, phraseScan}) {
    return new Promise(resolve => {
      const fromUpper = capitalize(fromTag.toLowerCase());
      const totalFound = scan.reduce((s, p) => s + p.found, 0);
      const baseTotal = TAG_BASELINE.reduce((s, p) => s + p.lower + p.upper, 0);

      const mismatches = scan.filter(s => s.missing || s.found !== s.expect);
      const phraseMissing = phraseScan.filter(p => p.missing || p.count === 0);

      let body = '';
      body += `<div style="margin-bottom:10px;">将把正文标签：</div>`;
      body += `<div style="padding:8px 12px; background:#f4ede2; border-radius:6px; margin-bottom:12px; font-family:'SF Mono',Menlo,monospace; font-size:12.5px; line-height:1.7; color:#3a3631;">`;
      body += `全局：<code>${fromTag.toLowerCase()}</code> / <code>${fromUpper}</code> → <strong>${toLower}</strong> / <strong>${toUpper}</strong><br>`;
      body += `大写位锁定：<code>[${fromUpper} Mandate]</code> → <strong>[${toUpper} Mandate]</strong><br>`;
      body += `大写位锁定：<code>${fromUpper} ends at</code> → <strong>${toUpper} ends at</strong>`;
      body += `</div>`;
      body += `<div style="margin-bottom:8px;">影响：<strong>${TAG_BASELINE.length}</strong> 个 prompts，找到 <strong>${totalFound}</strong> 处标签词（基线 ${baseTotal} 处）</div>`;

      if (mismatches.length) {
        body += `<div style="margin-top:14px; padding:10px 12px; background:#fdf3e1; border-left:3px solid #c4924b; border-radius:4px; color:#3a3631;">`;
        body += `<div style="font-weight:500; margin-bottom:6px;">⚠️ 与基线数量不一致（${mismatches.length} 处）：</div>`;
        mismatches.forEach(m => {
          body += `<div style="padding:4px 0; border-bottom:1px dashed #d5ccc2; font-size:12px;"><code>${m.name}</code>：实际 ${m.found}，基线 ${m.expect}${m.missing ? '（条目不存在）' : ''}</div>`;
        });
        body += `<div style="margin-top:6px; font-size:11.5px; color:#8a7e72;">仍可继续，按实际找到的位置全部替换。</div>`;
        body += `</div>`;
      }

      if (phraseMissing.length) {
        body += `<div style="margin-top:10px; padding:10px 12px; background:#fdf3e1; border-left:3px solid #c4924b; border-radius:4px; color:#3a3631;">`;
        body += `<div style="font-weight:500; margin-bottom:6px;">⚠️ 大写位 phrase 未找到（${phraseMissing.length} 处）：</div>`;
        phraseMissing.forEach(p => {
          body += `<div style="padding:4px 0; font-size:12px;"><code>${p.promptName}</code> · <code>${p.label}</code></div>`;
        });
        body += `<div style="margin-top:6px; font-size:11.5px; color:#8a7e72;">该位置无法回正为大写，仅按小写替换。可能 prompt 措辞已变更。</div>`;
        body += `</div>`;
      }

      if (!mismatches.length && !phraseMissing.length) {
        body += `<div style="margin-top:10px; padding:8px 12px; background:#eef4e7; border-left:3px solid #5b6e4a; border-radius:4px; font-size:12px; color:#3a3631;">✓ 与基线完全一致，大写位 phrase 全部锁定</div>`;
      }

      const $mask = $('<div class="hb-modal-mask"></div>');
      const $box = $('<div class="hb-modal-box"></div>');
      $box.html(
        '<h4 style="margin:0 0 12px; font-size:14px; color:#3a3631;">应用新正文标签？</h4>' +
        '<div style="margin-bottom:16px;">' + body + '</div>' +
        '<div style="display:flex; justify-content:flex-end; gap:8px;">' +
        '<button class="hb-modal-cancel">取消</button>' +
        '<button class="hb-modal-ok">应用</button>' +
        '</div>'
      );
      $mask.append($box).appendTo('body');
      requestAnimationFrame(() => $mask.addClass('show'));
      $box.find('.hb-modal-ok').on('click', () => close(true));
      $box.find('.hb-modal-cancel').on('click', () => close(false));
      function close(v) {
        $mask.removeClass('show');
        setTimeout(() => { $mask.remove(); resolve(v); }, 200);
      }
    });
  }

  async function applyTagRename(newTagRaw) {
    const newTag = newTagRaw.trim();
    if (!newTag) { toastr.warning('请输入新标签名'); return; }
    if (!/^[A-Za-z][A-Za-z0-9_]*$/.test(newTag)) {
      toastr.error('标签名只能含字母数字下划线，且首字符为字母');
      return;
    }
    const newLower = newTag.toLowerCase();
    const newUpper = capitalize(newLower);

    let preset;
    try { preset = getPreset('in_use'); }
    catch (e) {
      console.error('[此间小镇] 读取预设失败:', e);
      toastr.error('读取预设失败');
      return;
    }

    const currentTag = detectCurrentTag(preset);
    if (newLower === currentTag.toLowerCase()) {
      toastr.info(`当前已是 <${currentTag}>`);
      return;
    }

    const scan = scanTagFootprint(preset, currentTag);
    const phraseScan = scanPhraseFootprint(preset, currentTag);

    const ok = await showTagConfirm({
      fromTag: currentTag,
      toLower: newLower,
      toUpper: newUpper,
      scan, phraseScan,
    });
    if (!ok) return;

    const escapedCur = currentTag.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const fullRe = new RegExp(`(?<![A-Za-z0-9_])${escapedCur}(?![A-Za-z0-9_])`, 'gi');
    const targetIds = new Set(TAG_BASELINE.map(b => b.id));
    let totalReplaced = 0;
    let upperRecovered = 0;
    const unrecovered = [];

    try {
      await updatePresetWith('in_use', preset => {
        // 阶段 1：所有 baseline prompts 内 case-insensitive 全替换为 newLower
        preset.prompts.forEach(p => {
          if (!targetIds.has(p.id) || !p.content) return;
          const matches = (p.content.match(fullRe) || []).length;
          if (matches) {
            p.content = p.content.replace(fullRe, newLower);
            totalReplaced += matches;
          }
        });
        // 阶段 2：用 phrase 模板把大写位回正
        UPPER_PHRASE_PATTERNS.forEach(up => {
          const p = preset.prompts.find(x => x.id === up.promptId);
          if (!p || !p.content) { unrecovered.push(up.promptName + ' · ' + up.label + '（条目不存在）'); return; }
          const built = up.build(newLower);
          const before = (p.content.match(built.find) || []).length;
          if (before) { p.content = p.content.replace(built.find, built.replace); upperRecovered += before; }
          else unrecovered.push(up.promptName + ' · ' + up.label);
        });
        return preset;
      }, { render: 'immediate' });

      const msg = `已替换 ${totalReplaced} 处 → ${newLower}，其中 ${upperRecovered} 处大写位回正 → ${newUpper}`;
      toastr.success(msg);
      if (unrecovered.length) {
        toastr.warning('大写位未回正：' + unrecovered.join('；'), '请检查 prompt 措辞', { timeOut: 6000 });
      }
      syncPanelState();
    } catch (e) {
      console.error('[此间小镇] 替换正文标签失败:', e);
      toastr.error('替换失败，详见控制台');
    }
  }

