  function cancelFieldEdit($field) { $field.find('.hb-field-input').remove(); $field.removeClass('editing'); }
  function applyFieldEdit($field) {
    const $inp = $field.find('.hb-field-input');
    if (!$inp.length) return;
    const val = ($inp.val() || '').trim().replace(/[{}]/g, '');
    $field.find('.hb-field-val').text(val || '（空）');
    cancelFieldEdit($field);
    const field = $field.attr('data-field');
    if (field === 'wordcount') setWordCount(val);
    else if (field === 'language') setLanguage(val);
  }

