  // ============== UI: 拖动 ==============
  function viewportSize() {
    let w = window.innerWidth, h = window.innerHeight;
    try {
      if (window.parent && window.parent !== window) {
        w = window.parent.innerWidth || w;
        h = window.parent.innerHeight || h;
      }
    } catch (e) {}
    return { w, h };
  }

  function applySavedPosition($panel) {
    const { w, h } = viewportSize();
    const pos = lsRead(LS_POS_KEY, null);
    if (pos && Number.isFinite(pos.left) && Number.isFinite(pos.top)) {
      const maxLeft = Math.max(0, w - $panel.outerWidth());
      const maxTop  = Math.max(0, h - $panel.outerHeight());
      $panel.css({
        left: Math.min(pos.left, maxLeft) + 'px',
        top:  Math.min(pos.top, maxTop) + 'px',
        right: 'auto',
      });
    } else {
      $panel.css({ top: '80px', right: '20px' });
    }
  }

  function bindDrag($panel) {
    let dragState = null;
    $panel.on('pointerdown.hb-drag', '.hb-header', function (e) {
      if ($(e.target).closest('.hb-close, .hb-theme-toggle, .hb-help').length) return;
      if (e.button !== undefined && e.button !== 0) return;
      const offset = $panel.offset();
      dragState = {
        offsetX: e.pageX - offset.left,
        offsetY: e.pageY - offset.top,
